package io.github.mymayankyadav.lemma;
import android.content.*;import android.app.*;import android.database.Cursor;import android.net.Uri;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;
public class NativeDataReprosTest {
 static class Prefs implements SharedPreferences {Map<String,Object> m=new HashMap<>();public String getString(String k,String d){return(String)m.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return(Boolean)m.getOrDefault(k,d);}public Editor edit(){return new Editor(){Map<String,Object>w=new HashMap<>();Set<String>r=new HashSet<>();boolean clear;public Editor putString(String k,String v){w.put(k,v);return this;}public Editor putBoolean(String k,boolean v){w.put(k,v);return this;}public Editor remove(String k){r.add(k);return this;}public Editor clear(){clear=true;return this;}public void apply(){if(clear)m.clear();for(String k:r)m.remove(k);m.putAll(w);}};}}
 static class Row implements Cursor {Object[] data;Row(Object...d){data=d;}boolean moved;public boolean moveToFirst(){moved=true;return true;}public boolean moveToNext(){if(moved)return false;moved=true;return true;}public String getString(int i){return(String)data[i];}public long getLong(int i){return((Number)data[i]).longValue();}public int getInt(int i){return((Number)data[i]).intValue();}public boolean isNull(int i){return data[i]==null;}public void close(){}}
 static class Ctx extends Context {Map<String,Prefs> p=new HashMap<>();final AlarmManager alarms=new AlarmManager();final NotificationManager notifications=new NotificationManager();File cache;Ctx()throws Exception{cache=Files.createTempDirectory("lemma-native-test").toFile();}public SharedPreferences getSharedPreferences(String n,int m){return p.computeIfAbsent(n,k->new Prefs());}public Object getSystemService(String n){return ALARM_SERVICE.equals(n)?alarms:notifications;}public File getCacheDir(){return cache;}public ContentResolver getContentResolver(){return new ContentResolver(){public String getType(Uri u){return "application/pdf";}public Cursor query(Uri u,String[]p,String s,String[]a,String o){return new Row(u.toString().substring(u.toString().lastIndexOf('/')+1),4L);}public InputStream openInputStream(Uri u){return new ByteArrayInputStream(new byte[]{1,2,3,4});}};}}
 @Before public void reset(){PendingIntent.all.clear();ShareIntake.take();}
 @Test public void signoutMustCancelSnoozedPrivateReminder()throws Exception{Ctx c=new Ctx();JSONObject item=new JSONObject().put("id","block:private-A").put("at",System.currentTimeMillis()+60000).put("title","Owner A private project").put("body","private context");Reminders.set(c,new JSONArray().put(item));new Reminders().onReceive(c,new Intent(Reminders.ACTION_DO).putExtra("item",item.toString()).putExtra("action","later"));Reminders.reset(c);System.out.println("alarms after sign-out empty schedule="+c.alarms.armed.size()+" snoozed="+c.getSharedPreferences("lemma.reminders",0).getString("snoozed","[]"));assertEquals("sign-out must remove the owner's snoozed alarm",0,c.alarms.armed.size());}
 @Test public void unsyncedThoughtMustNotBeEvictedByLaterActions()throws Exception{Ctx c=new Ctx();String original=PendingActions.add(c,"thought","entry-A",1,"The only copy of an important proof idea");for(int i=0;i<20;i++)PendingActions.add(c,i%2==0?"pause":"resume","entry-A",1,null);JSONArray items=PendingActions.all(c);boolean found=false;for(int i=0;i<items.length();i++)if(original.equals(items.getJSONObject(i).getString("id")))found=true;System.out.println("queue size="+items.length()+" original thought preserved="+found);assertTrue("unacknowledged thought must not disappear",found);}
 @Test public void multipleSharesMustKeepEveryPendingFileReadable()throws Exception{Ctx c=new Ctx();ShareIntake.capture(c,new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,Uri.parse("content://fixture/first.pdf")));ShareIntake.capture(c,new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,Uri.parse("content://fixture/second.pdf")));JSONArray items=ShareIntake.take();assertEquals(2,items.length());File first=new File(items.getJSONObject(0).getJSONArray("files").getJSONObject(0).getString("path"));System.out.println("first queued shared file exists="+first.exists());assertTrue("queued shared document must remain readable",first.isFile());}
 @Test public void signoutMustDismissAlreadyPostedReminders()throws Exception{Ctx c=new Ctx();Reminders.post(c,new JSONObject().put("id","private-A").put("title","Owner A private study").put("body","private"));assertEquals(1,c.notifications.posted.size());Reminders.reset(c);assertEquals("sign-out must dismiss posted private reminders",0,c.notifications.posted.size());}
 @Test public void ordinaryPendingRemovePreservesUnrelatedItems()throws Exception{Ctx c=new Ctx();String a=PendingActions.add(c,"thought","entry-A",1,"A"),b=PendingActions.add(c,"thought","entry-A",1,"B");PendingActions.remove(c,Collections.singleton(a));assertEquals(b,PendingActions.all(c).getJSONObject(0).getString("id"));}
 @Test public void snoozeWorksBeforeSignout()throws Exception{Ctx c=new Ctx();JSONObject item=new JSONObject().put("id","due").put("at",System.currentTimeMillis()+60000);new Reminders().onReceive(c,new Intent(Reminders.ACTION_DO).putExtra("item",item.toString()).putExtra("action","later"));assertEquals(1,c.alarms.armed.size());}
 @Test public void acknowledgesOnlyTheCopiedSharedFile()throws Exception{
  Ctx c=new Ctx();ShareIntake.capture(c,new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,Uri.parse("content://fixture/first.pdf")));
  ShareIntake.capture(c,new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,Uri.parse("content://fixture/second.pdf")));
  JSONArray items=ShareIntake.take();String first=items.getJSONObject(0).getJSONArray("files").getJSONObject(0).getString("path"),second=items.getJSONObject(1).getJSONArray("files").getJSONObject(0).getString("path");
  ShareIntake.ack(c,new JSONArray().put(first));assertFalse(new File(first).exists());assertTrue(new File(second).exists());
 }
 @Test public void legacyQueueAdoptionPreservesItsReceiptAndThought()throws Exception{
  Ctx c=new Ctx();SessionStore.current=null;String id=PendingActions.add(c,"thought","entry",1,"Only copy of the proof");
  PendingActions.adoptUnowned(c,"A","phone");SessionStore.current=new SessionStore.Session("https://example.invalid","key","token",Long.MAX_VALUE);SessionStore.current.ownerId="B";
  assertEquals(0,PendingActions.forOwner(c).length());SessionStore.current.ownerId="A";
  JSONObject thought=PendingActions.forOwner(c).getJSONObject(0);assertEquals(id,thought.getString("id"));assertEquals("Only copy of the proof",thought.getString("text"));SessionStore.current=null;
 }

}

